import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { FiArrowRight, FiStar, FiBriefcase, FiUsers, FiCheck, FiTrendingUp, FiShield, FiAward, FiZap, FiClock, FiChevronLeft, FiChevronRight } from 'react-icons/fi';
import TrustIndicators from '../components/trust/TrustIndicators';
import GlassCard from '../components/animations/GlassCard';

const Home = () => {
  const [currentTestimonial, setCurrentTestimonial] = useState(0);
  const [stats, setStats] = useState({ students: 0, projects: 0, success: 0, clients: 0 });

  // Animated Counter
  useEffect(() => {
    const targets = { students: 5247, projects: 1893, success: 95, clients: 428 };
    const duration = 2000;
    const steps = 50;
    const increment = {
      students: targets.students / steps,
      projects: targets.projects / steps,
      success: targets.success / steps,
      clients: targets.clients / steps
    };
    
    let current = 0;
    const timer = setInterval(() => {
      current++;
      setStats({
        students: Math.min(Math.floor(increment.students * current), targets.students),
        projects: Math.min(Math.floor(increment.projects * current), targets.projects),
        success: Math.min(Math.floor(increment.success * current), targets.success),
        clients: Math.min(Math.floor(increment.clients * current), targets.clients)
      });
      if (current >= steps) clearInterval(timer);
    }, duration / steps);
    
    return () => clearInterval(timer);
  }, []);

  // Auto-rotate testimonials
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTestimonial(prev => (prev + 1) % testimonials.length);
    }, 5000);
    return () => clearInterval(timer);
  }, []);

  const features = [
    { icon: <FiStar size={32}/>, title: 'AI-Powered Matching', desc: 'Our intelligent algorithm matches students with projects based on skills for 95% success rate.', color: 'from-yellow-400 to-orange-500' },
    { icon: <FiShield size={32}/>, title: 'Secure Payments', desc: 'Payment protection with escrow system. Your money is safe until project completion.', color: 'from-green-400 to-teal-500' },
    { icon: <FiZap size={32}/>, title: 'Instant Notifications', desc: 'Get real-time updates on applications, messages, and project milestones.', color: 'from-blue-400 to-indigo-500' },
    { icon: <FiAward size={32}/>, title: 'Verified Profiles', desc: 'All users are verified with badges. Build trust with proven track records.', color: 'from-purple-400 to-pink-500' },
  ];

  const testimonials = [
    { name: 'Sarah Mitchell', role: 'Computer Science Student', avatar: 'SM', rating: 5, text: 'I landed my first freelance project within a week! The skill matching is incredibly accurate. Made $2,500 in my first month!', projects: 12 },
    { name: 'James Rodriguez', role: 'Design Student', avatar: 'JR', rating: 5, text: 'As a design student, I struggled to find clients. StudentHub connected me with amazing projects that match my skills perfectly!', projects: 8 },
    { name: 'Emily Chen', role: 'Marketing Student', avatar: 'EC', rating: 5, text: 'The platform is professional and easy to use. Clients are serious and payments are on time. Highly recommend!', projects: 15 },
    { name: 'Michael Kumar', role: 'Web Dev Student', avatar: 'MK', rating: 5, text: 'From zero experience to 10 completed projects! StudentHub gave me the opportunity to build a real portfolio.', projects: 10 }
  ];

  const featuredProjects = [
    { title: 'E-commerce Website', budget: '$1,200', duration: '3 weeks', level: 'Intermediate', skills: ['React', 'Node.js', 'MongoDB'], applications: 23 },
    { title: 'Mobile App Design', budget: '$800', duration: '2 weeks', level: 'Beginner', skills: ['Figma', 'UI/UX', 'Prototyping'], applications: 18 },
    { title: 'Content Writing', budget: '$500', duration: '1 week', level: 'Beginner', skills: ['SEO', 'Copywriting', 'Research'], applications: 31 },
    { title: 'Data Analysis Project', budget: '$950', duration: '2 weeks', level: 'Advanced', skills: ['Python', 'Pandas', 'Visualization'], applications: 15 }
  ];

  const companies = ['TechCorp', 'StartupHub', 'DesignLab', 'CodeAcademy', 'DigitalPro', 'InnovateCo'];

  return (
    <div className="overflow-x-hidden">
      
      {/* HERO SECTION */}
      <section className="relative bg-gradient-to-br from-gray-900 via-green-900 to-gray-900 text-white py-24 lg:py-32 overflow-hidden">
        {/* Animated Background */}
        <div className="absolute inset-0 opacity-20">
          <div className="absolute top-20 left-10 w-96 h-96 bg-green-500 rounded-full blur-3xl animate-float"></div>
          <div className="absolute bottom-20 right-10 w-80 h-80 bg-blue-500 rounded-full blur-3xl animate-float" style={{animationDelay: '2s'}}></div>
          <div className="absolute top-1/2 left-1/2 w-64 h-64 bg-yellow-500 rounded-full blur-3xl animate-float" style={{animationDelay: '4s'}}></div>
        </div>

        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid lg:grid-cols-2 gap-12 items-center">
            
            {/* Left Content */}
            <div className="animate-slide-in-left">
              <div className="inline-flex items-center space-x-2 px-4 py-2 bg-white bg-opacity-10 backdrop-blur-sm rounded-full mb-6 border border-white border-opacity-20">
                <FiTrendingUp className="text-green-400" size={18} />
                <span className="text-green-200 text-sm font-semibold">Trusted by 5,000+ Students</span>
              </div>

              <h1 className="text-5xl lg:text-7xl font-black leading-tight mb-6 bg-gradient-to-r from-white via-green-200 to-blue-200 bg-clip-text text-transparent">
                Build Your Career<br/>One Project<br/>at a Time
              </h1>

              <p className="text-xl text-gray-300 mb-8 leading-relaxed max-w-xl">
                The #1 freelance marketplace designed exclusively for students. Get matched with perfect projects using AI-powered skill matching.
              </p>

              <div className="flex flex-col sm:flex-row gap-4 mb-12">
                <Link to="/register" className="group relative px-8 py-4 bg-gradient-to-r from-green-500 to-green-600 text-white rounded-xl font-bold text-lg hover:from-green-600 hover:to-green-700 transition-all shadow-2xl hover:shadow-green-500/50 hover:scale-105 transform flex items-center justify-center space-x-2">
                  <span>Get Started Free</span>
                  <FiArrowRight className="group-hover:translate-x-1 transition-transform"/>
                </Link>
                <Link to="/browse" className="px-8 py-4 border-2 border-white text-white rounded-xl font-bold text-lg hover:bg-white hover:text-gray-900 transition-all backdrop-blur-sm flex items-center justify-center space-x-2">
                  <FiBriefcase size={20}/>
                  <span>Browse Projects</span>
                </Link>
              </div>

              {/* Trust Badges */}
              <div className="flex items-center space-x-6 text-sm">
                <div className="flex items-center space-x-2">
                  <FiCheck className="text-green-400" size={20}/>
                  <span className="text-gray-300">100% Free to Join</span>
                </div>
                <div className="flex items-center space-x-2">
                  <FiShield className="text-green-400" size={20}/>
                  <span className="text-gray-300">Secure Payments</span>
                </div>
              </div>
            </div>

            {/* Right - Stats Cards - REPLACE WITH GLASS CARDS */}
            <div className="grid grid-cols-2 gap-4 animate-slide-in-right">
              {[
                { label: 'Active Students', value: stats.students.toLocaleString(), icon: <FiUsers size={24}/>, gradient: 'from-blue-500 to-indigo-600' },
                { label: 'Projects Posted', value: stats.projects.toLocaleString(), icon: <FiBriefcase size={24}/>, gradient: 'from-green-500 to-teal-600' },
                { label: 'Success Rate', value: `${stats.success}%`, icon: <FiAward size={24}/>, gradient: 'from-yellow-500 to-orange-600' },
                { label: 'Happy Clients', value: stats.clients.toLocaleString(), icon: <FiStar size={24}/>, gradient: 'from-purple-500 to-pink-600' }
              ].map((stat, i) => (
                <GlassCard key={i} className="p-6" blur="lg">
                  <div className={`w-12 h-12 bg-gradient-to-br ${stat.gradient} rounded-xl flex items-center justify-center mb-3 text-white shadow-lg`}>
                    {stat.icon}
                  </div>
                  <p className="text-3xl font-black text-white mb-1">{stat.value}</p>
                  <p className="text-gray-200 text-sm font-medium">{stat.label}</p>
                </GlassCard>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* AS SEEN ON */}
      <section className="bg-white py-12 border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <p className="text-center text-gray-500 text-sm font-semibold mb-8 uppercase tracking-wider">Trusted by students from</p>
          <div className="flex flex-wrap justify-center items-center gap-12 opacity-60">
            {companies.map((company, i) => (
              <div key={i} className="text-2xl font-black text-gray-800 hover:text-green-600 transition-colors cursor-default">
                {company}
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* FEATURES */}
      <section className="py-24 bg-gray-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16 animate-fade-in">
            <span className="px-4 py-2 bg-green-100 text-green-700 rounded-full text-sm font-bold uppercase tracking-wide">Why StudentHub</span>
            <h2 className="text-5xl font-black text-gray-900 mt-6 mb-4">Everything You Need to Succeed</h2>
            <p className="text-xl text-gray-600 max-w-2xl mx-auto">Built specifically for students. Every feature designed to help you land projects faster.</p>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
            {features.map((f, i) => (
              <div key={i} className="group relative bg-white rounded-3xl p-8 hover:shadow-2xl transition-all duration-500 border border-gray-100 hover:border-transparent overflow-hidden animate-slide-up" style={{animationDelay: `${i * 0.1}s`}}>
                <div className={`absolute inset-0 bg-gradient-to-br ${f.color} opacity-0 group-hover:opacity-5 transition-opacity duration-500`}></div>
                <div className={`relative w-16 h-16 bg-gradient-to-br ${f.color} rounded-2xl flex items-center justify-center mb-6 text-white shadow-lg group-hover:scale-110 transition-transform duration-500`}>
                  {f.icon}
                </div>
                <h3 className="text-xl font-black text-gray-900 mb-3">{f.title}</h3>
                <p className="text-gray-600 leading-relaxed">{f.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* TESTIMONIALS */}
      <section className="py-24 bg-gradient-to-br from-green-600 via-green-700 to-teal-700 text-white relative overflow-hidden">
        <div className="absolute inset-0 opacity-10">
          <div className="absolute top-10 right-20 w-96 h-96 bg-white rounded-full blur-3xl"></div>
          <div className="absolute bottom-10 left-20 w-80 h-80 bg-yellow-300 rounded-full blur-3xl"></div>
        </div>

        <div className="relative max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <span className="px-4 py-2 bg-white bg-opacity-20 backdrop-blur-sm text-white rounded-full text-sm font-bold uppercase tracking-wide">Success Stories</span>
            <h2 className="text-5xl font-black mt-6 mb-4">Students Love StudentHub</h2>
            <p className="text-xl text-green-100 max-w-2xl mx-auto">Real feedback from students building their careers on our platform</p>
          </div>

          <div className="relative bg-white bg-opacity-10 backdrop-blur-xl rounded-3xl p-12 border border-white border-opacity-20">
            <div className="flex items-start space-x-6">
              <div className="flex-shrink-0">
                <div className="w-20 h-20 bg-gradient-to-br from-green-400 to-teal-500 rounded-2xl flex items-center justify-center text-white text-2xl font-black shadow-2xl">
                  {testimonials[currentTestimonial].avatar}
                </div>
              </div>
              <div className="flex-1">
                <div className="flex items-center space-x-2 mb-4">
                  {[...Array(testimonials[currentTestimonial].rating)].map((_, i) => (
                    <FiStar key={i} className="text-yellow-400 fill-current" size={20}/>
                  ))}
                </div>
                <p className="text-2xl font-semibold text-white mb-6 leading-relaxed">{testimonials[currentTestimonial].text}</p>
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-lg font-black text-white">{testimonials[currentTestimonial].name}</p>
                    <p className="text-green-200">{testimonials[currentTestimonial].role}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-3xl font-black text-white">{testimonials[currentTestimonial].projects}</p>
                    <p className="text-green-200 text-sm">Projects Completed</p>
                  </div>
                </div>
              </div>
            </div>

            {/* Navigation */}
            <div className="flex items-center justify-center space-x-4 mt-8">
              <button onClick={() => setCurrentTestimonial((currentTestimonial - 1 + testimonials.length) % testimonials.length)} className="p-3 bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full transition-all">
                <FiChevronLeft size={24}/>
              </button>
              <div className="flex space-x-2">
                {testimonials.map((_, i) => (
                  <button key={i} onClick={() => setCurrentTestimonial(i)} className={`w-2 h-2 rounded-full transition-all ${i === currentTestimonial ? 'bg-white w-8' : 'bg-white bg-opacity-50'}`}></button>
                ))}
              </div>
              <button onClick={() => setCurrentTestimonial((currentTestimonial + 1) % testimonials.length)} className="p-3 bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full transition-all">
                <FiChevronRight size={24}/>
              </button>
            </div>
          </div>
        </div>
      </section>

      {/* Testimonials Section ends */}

      {/* Trust Indicators - ADD THIS */}
      <TrustIndicators />

      {/* FEATURED PROJECTS */}
      <section className="py-24 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <span className="px-4 py-2 bg-blue-100 text-blue-700 rounded-full text-sm font-bold uppercase tracking-wide">Hot Projects</span>
            <h2 className="text-5xl font-black text-gray-900 mt-6 mb-4">Featured Opportunities</h2>
            <p className="text-xl text-gray-600 max-w-2xl mx-auto">Top projects students are applying to right now</p>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6">
            {featuredProjects.map((project, i) => (
              <div key={i} className="group bg-white border-2 border-gray-100 rounded-2xl p-6 hover:border-green-500 hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 cursor-pointer">
                <div className="flex items-center justify-between mb-4">
                  <span className={`px-3 py-1 rounded-full text-xs font-bold ${project.level === 'Beginner' ? 'bg-green-100 text-green-700' : project.level === 'Intermediate' ? 'bg-yellow-100 text-yellow-700' : 'bg-red-100 text-red-700'}`}>{project.level}</span>
                  <span className="text-xs text-gray-500"><FiUsers size={12} className="inline mr-1"/>{project.applications} applicants</span>
                </div>
                <h3 className="text-lg font-black text-gray-900 mb-3 group-hover:text-green-600 transition-colors">{project.title}</h3>
                <div className="flex flex-wrap gap-2 mb-4">
                  {project.skills.slice(0, 2).map((skill, idx) => (
                    <span key={idx} className="px-2 py-1 bg-gray-100 text-gray-700 rounded text-xs font-semibold">{skill}</span>
                  ))}
                  {project.skills.length > 2 && <span className="px-2 py-1 bg-gray-100 text-gray-500 rounded text-xs">+{project.skills.length - 2}</span>}
                </div>
                <div className="flex items-center justify-between text-sm pt-4 border-t border-gray-100">
                  <div className="flex items-center space-x-1 text-green-600 font-black">
                    <span>{project.budget}</span>
                  </div>
                  <div className="flex items-center space-x-1 text-gray-500">
                    <FiClock size={14}/>
                    <span>{project.duration}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
          <div className="text-center mt-12">
            <Link to="/browse" className="inline-flex items-center space-x-2 px-8 py-4 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 transition-all shadow-lg hover:shadow-green-500/50 hover:scale-105 transform">
              <span>View All Projects</span>
              <FiArrowRight/>
            </Link>
          </div>
        </div>
      </section>

      {/* FINAL CTA */}
      <section className="relative bg-gradient-to-r from-gray-900 via-green-900 to-gray-900 py-24 overflow-hidden">
        <div className="absolute inset-0 opacity-20">
          <div className="absolute top-0 left-1/4 w-96 h-96 bg-green-500 rounded-full blur-3xl animate-float"></div>
          <div className="absolute bottom-0 right-1/4 w-96 h-96 bg-blue-500 rounded-full blur-3xl animate-float" style={{animationDelay: '3s'}}></div>
        </div>
        <div className="relative max-w-4xl mx-auto px-4 text-center">
          <h2 className="text-5xl lg:text-6xl font-black text-white mb-6">Ready to Start Your Journey?</h2>
          <p className="text-xl text-gray-300 mb-12 max-w-2xl mx-auto">Join thousands of students already building successful freelance careers on StudentHub.</p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Link to="/register" className="px-10 py-5 bg-gradient-to-r from-green-500 to-green-600 text-white rounded-xl font-black text-lg hover:from-green-600 hover:to-green-700 transition-all shadow-2xl hover:shadow-green-500/50 hover:scale-105 transform">Create Free Account</Link>
            <Link to="/browse" className="px-10 py-5 border-2 border-white text-white rounded-xl font-black text-lg hover:bg-white hover:text-gray-900 transition-all backdrop-blur-sm">Browse Projects</Link>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;
